  local function after_close()
    if VRFW.param.has(KEY_OPEN_BOARD) then
      VRFW.param.clear(KEY_OPEN_BOARD)
    end
  end

  if VRFW.host ~= nil then
    VRFW.host.on(STEM, "OnInit", {id = "CharacterReforged.team_dock_skill_table", phase = "before", fn = function()
